// Ported from the Node app's Sequelize model FeedbackLog (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class FeedbackLogConfiguration : IEntityTypeConfiguration<FeedbackLog>
{
    public void Configure(EntityTypeBuilder<FeedbackLog> builder)
    {
        builder.ToTable("feedback_logs");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.FeedbackId).HasColumnName("feedback_id");
        builder.Property(e => e.Action).HasColumnName("action").HasColumnType("nvarchar(30)").HasMaxLength(30).IsRequired();
        builder.Property(e => e.Level).HasColumnName("level");
        builder.Property(e => e.Note).HasColumnName("note").HasColumnType("nvarchar(500)").HasMaxLength(500);
        builder.Property(e => e.ByName).HasColumnName("by_name").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.HasIndex(e => e.FeedbackId).HasDatabaseName("ix_fblog_feedback");
        builder.HasOne(e => e.Feedback).WithMany(p => p.FeedbackLogs).HasForeignKey(e => e.FeedbackId).OnDelete(DeleteBehavior.NoAction);
    }
}
